/**
 * In-memory notification preference store.
 *
 * This is intentionally process-local so the Server Action can demonstrate the
 * toggle + revalidate flow without a database. In a real app you would read
 * and write this from your data layer keyed on the authenticated user.
 */

// Default to "on" so the first toggle visibly flips to "off".
let notificationsEnabled = true;

export function isNotificationsEnabled(): boolean {
  return notificationsEnabled;
}

/** Flips the preference and returns the new value. */
export function toggleNotifications(): boolean {
  notificationsEnabled = !notificationsEnabled;
  return notificationsEnabled;
}

