"use server";

import { revalidatePath } from "next/cache";
import { toggleNotifications, isNotificationsEnabled } from "./store";

/**
 * Toggles the user's notification preference between on/off.
 *
 * After mutating the data, we call `revalidatePath` (Next.js's recommended
 * way to refresh the current route's data from within a Server Action). This
 * purges the client Router Cache for this path, so the current page
 * re-fetches and re-renders with the updated preference WITHOUT navigating
 * to a different URL and WITHOUT a full page reload.
 */
export async function toggleNotificationsAction(): Promise<void> {
  toggleNotifications();

  // Revalidate the current route so the page refreshes in place.
  revalidatePath("/");
}

