import { toggleNotificationsAction } from "./notifications/actions";
import { isNotificationsEnabled } from "./notifications/store";

export default function Home() {
  const enabled = isNotificationsEnabled();

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {enabled ? "on" : "off"}.</p>

      {/* The form action is the Server Action. After it runs, revalidatePath
          refreshes this route's data in place (no redirect, no full reload). */}
      <form action={toggleNotificationsAction}>
        <button type="submit">
          Turn notifications {enabled ? "off" : "on"}
        </button>
      </form>
    </main>
  );
}

